const now=new Date();
const bh=parseInt(now.toLocaleString('en-US',{timeZone:'America/Sao_Paulo',hour:'numeric',hour12:false}));
const bd=new Date(now.toLocaleString('en-US',{timeZone:'America/Sao_Paulo'})).getDay();
if(bd===0||bd===6||bh<8||bh>=18)return[];
return[{json:{hora_br:bh}}];

const raw=$input.all()[0].json;
const leads=Array.isArray(raw)?raw:(raw&&raw.id?[raw]:[]);
if(!leads.length)return[];
return leads.map(l=>({json:l}));

const lead=$input.first().json;
const fc=parseInt(lead.followup_count)||0;
const GK=$env.OPENAI_API_KEY;
const hist=Array.isArray(lead.sdr_history)?lead.sdr_history:[];
const lastMsgs=hist.slice(-8).map(h=>(h.role==='user'?'Lead':'SDR')+': '+(h.content||'').substring(0,80)).join('\n')||'(sem historico)';
const ins=[
  'FU1: Escritorio nao respondeu em 3 dias. Lembrete natural, max 3 linhas. Casual, sem pressao. Termine com (se nao fizer sentido, e so falar que paro por aqui).',
  'FU2: Adicione valor - resultado concreto que escritorios alcancam quando posicionamento, funil, automacoes e midia ficam conectados. Max 3 linhas. Termine com pergunta aberta.',
  'FU3: UMA pergunta consultiva sobre o maior gargalo em captacao digital hoje: gerar oportunidades, converter contatos ou organizar follow-up. Curto e direto. Max 2 linhas.',
  'FU4: Urgencia leve e verdadeira - agenda limitada este mes para novos diagnosticos. Max 3 linhas. Tom respeitoso.',
  'FU5 (breakup): Informe que vai parar de entrar em contato, deixe porta aberta para o futuro. Max 2 linhas.'
];
const sys='Voce e especialista em captacao digital juridica. A Nexos cria ecossistemas de captacao para escritorios: posicionamento, funis, automacoes, orientacoes/scripts de videos, edicao de videos e midia paga quando fizer sentido. Escreva UMA mensagem de follow-up para WhatsApp. REGRAS: NUNCA comece com Ola/Oi/cumprimento generico. Tom casual brasileiro. NAO mencione precos. NAO reduza a oferta a midia paga isolada. Retorne APENAS a mensagem, sem aspas. '+ins[Math.min(fc,4)];
const uc='Escritorio: '+(lead.business_name||'Lead')+'\nCidade: '+(lead.city||'N/A')+'/'+(lead.state||'')+'\nNota Google: '+(lead.google_rating||'nao informado')+' ('+(lead.google_reviews_count||0)+' avaliacoes)'+'\nDores: '+(lead.pain_signals||'nao identificado')+'\nHistorico recente:\n'+lastMsgs;
const r=await this.helpers.httpRequest({method:'POST',url:'https://api.openai.com/v1/chat/completions',headers:{'Authorization':'Bearer '+GK,'Content-Type':'application/json'},body:{model:'gpt-4o-mini',max_tokens:250,temperature:0.88,messages:[{role:'system',content:sys},{role:'user',content:uc}]},ignoreHttpStatusErrors:true});
const msg=r?.choices?.[0]?.message?.content?.trim()||'';
const fallbacks=['Apenas verificando se minha mensagem chegou. Faz sentido conversar sobre captacao digital para o escritorio?','Quando posicionamento, funil e follow-up ficam soltos, muita oportunidade boa se perde. Faz sentido eu te mostrar como estruturamos isso?','Hoje o maior gargalo de voces e gerar oportunidades novas, converter contatos ou organizar o acompanhamento?','Estou priorizando poucos diagnosticos este mes para conseguir olhar cada escritorio com cuidado.','Vou encerrar meu contato por aqui. Se no futuro fizer sentido, pode me chamar a qualquer momento.'];
return[{json:{...lead,generated_message:msg||fallbacks[Math.min(fc,4)]}}];

const d=$input.first().json;
const fc=parseInt(d.followup_count)||0;
const msg=d.generated_message||'';
const delays=[3,3,4,5,6];
const isLast=fc>=4;
const newCount=fc+1;
const nextAt=isLast?null:new Date(Date.now()+(delays[fc]||3)*86400000).toISOString();
const newStatus=isLast?'perdido':'followup_'+newCount;
const history=Array.isArray(d.sdr_history)?d.sdr_history:[];
const updHist=[...history,{role:'assistant',content:msg,ts:new Date().toISOString(),type:'followup',followup_num:newCount}];
return[{json:{...d,visible_message:msg,new_followup_count:newCount,next_followup_at:nextAt,new_status:newStatus,updated_history:updHist}}];
